      warehouse: batch.warehouse,
      startedAt: batch.createdAt,
      endedAt: batch.active ? '' : batch.updatedAt,
      totalQty: netQty,
      grossQty: grossQty,
      netQty: netQty,
      unit: prints.isEmpty ? 'kg' : prints.first.unit,
